using System;
using UnityEngine;

namespace CloudGarden.ShadowPuzzle
{
    [Serializable] public struct TorchPiece
    {
        public string label;
        public Mesh mesh;
        public Material[] materials;
        // Pose on the turntable at yaw 0, in workbench metres (the turntable axis is TorchProjection.Axis).
        public Vector3 position,euler;
    }

    // A fixed pile of everyday objects on a turntable. One flashlight position and one turntable angle make its
    // shadow a picture. Generated by Tools/ShadowArt/build_torch.py and MetaHackthone > Shadow Workshop >
    // Import torch levels. The target is the meshes' own shadow at the solution, so it is always reachable.
    [CreateAssetMenu(menuName="Shadow Workshop/Torch level")]
    public sealed class TorchLevel : ScriptableObject
    {
        public const string ResourceFolder="ShadowArt/Torch/";
        public string title,button;
        [TextArea(2,4)] public string riddle,hint,complete;
        public Color accent=new Color(.95f,.62f,.30f);
        public TorchPiece[] pieces=Array.Empty<TorchPiece>();
        [Header("Answer")]
        public Vector3 solutionLight=new Vector3(.10f,.22f,-.40f);
        public float solutionYaw,startYaw=140;
        [Header("Eased match (position and size of the shadow do not matter)")]
        [Tooltip("Cells of the 64x64 normalised compare grid.")] public int tolerance=1;
        [Range(0,1)] public float coverMin=.90f,spillMax=.10f,iouMin=.62f;
        public static TorchLevel Load(string id)=>string.IsNullOrEmpty(id)?null:Resources.Load<TorchLevel>(ResourceFolder+id);
    }
}
